-- ADR-0054 slice 3a: a pharmacy employs Staff, so the hospital-only guard moves from Staff and access onto every Staff child.
DROP TRIGGER workforce_hospital_establishment ON workforce_staff;
DROP TRIGGER workforce_hospital_establishment ON workforce_hospital_access;
CREATE TRIGGER workforce_hospital_establishment BEFORE INSERT OR UPDATE OF tenant_id,hospital_id ON workforce_attendance_corrections FOR EACH ROW EXECUTE FUNCTION workforce_require_hospital_establishment();
